  computeClipAssetPaths(name = ClipsAPI.defaultClipSet): VtArray<string> {
    const explicit = this.getClipAssetPaths(name)
    if (explicit.size > 0) return explicit
    const template = this.getClipTemplateAssetPath(name)
    if (!template) return typedField([], 'asset[]')
    const match = template.match(/(#+)(?=[^#]*$)/)
    if (!match) return typedField([], 'asset[]')
    const width = match[1]!.length
    const start = this.getClipTemplateStartTime(name)
    const end = this.getClipTemplateEndTime(name)
    const stride = this.getClipTemplateStride(name)
    const result: string[] = []
    for (let frame = start; frame <= end; frame += stride) {
      const number = Number.isInteger(frame) ? String(frame).padStart(width, '0') : String(frame)
      result.push(template.slice(0, match.index) + number + template.slice(match.index! + width))
    }
    return typedField(result, 'asset[]')
  }

  async generateClipManifest(name = ClipsAPI.defaultClipSet): Promise<Layer> {
    const root = this.stage.getRootLayer()
    const layers: Layer[] = []
    for (const asset of this.computeClipAssetPaths(name)) {
      const path = typeof asset === 'string' ? asset
        : typeof asset === 'object' && asset !== null && 'assetPath' in asset
          ? String((asset as { assetPath: unknown }).assetPath) : String(asset)
      // Usd_Clip::_GetLayerForClip (clip.cpp:873-905): a clip layer that
      // cannot be opened is reported and contributes an empty layer.
      const layer = await Layer.findOrOpen(root.resolveAsset(path))
      if (layer) layers.push(layer)
      else TfDiagnosticMgr.GetInstance().postWarning(`Unable to open clip layer @${path}@`)
    }
    return ClipsAPI.generateClipManifestFromLayers(layers, this.getClipPrimPath(name))
  }
  static generateClipManifestFromLayers(layers: Layer[], primPath: string): Layer {
    if (!primPath.startsWith('/') || primPath === '/' || primPath.includes('.')) {
      throw new Error(`GenerateClipManifestFromLayers: <${primPath}> is not a prim path`)
    }
    if (layers.some((layer) => !(layer instanceof Layer))) {
      throw new Error('GenerateClipManifestFromLayers: invalid clip layer')
    }
    const manifest = Layer.createAnonymous('generatedClipManifest.usda')
    // Usd_GenerateClipManifest (clipSet.cpp:90-160): every attribute under
    // primPath with a typeName and variability and with time samples or a
    // spline in some clip layer is declared. When no clip authors time
    // samples for it and some clip authors a spline (_SplineWins,
    // clipSet.cpp:43-50), the declaration carries an empty spline of the
    // attribute's value type.
    sdfChangeBlock(() => {
      for (const layer of layers) {
        layer.traverse(primPath, path => {
          if (!SdfPath.fromString(path).isPropertyPath()) return
          if (layer.getSpecType(path) !== 'attribute' ||
              !layer.hasField(path, 'typeName') || !layer.hasField(path, 'variability')) return
          const typeName = String(layer.getField(path, 'typeName'))
          const variability = layer.getField(path, 'variability') as SdfVariability
          const hasTimeSamples = layer.listTimeSamplesForPath(path).length !== 0
          const hasSpline = layer.hasField(path, 'spline')
          if (!hasTimeSamples && !hasSpline) return
          if (!manifest.hasSpec(path)) {
            sdfJustCreatePrimAttributeInLayer(manifest, path, typeName, variability)
            if (hasSpline && !hasTimeSamples) {
              manifest.setField(path, 'spline', new TsSpline(Ts_GetTypeFromTypeName(typeName)))
            }
          } else if (hasTimeSamples) {
            manifest.eraseField(path, 'spline')
          }
        })
      }
    })
    return manifest
  }
