type ClipSet = Record<string, unknown>

// A clip field as its value type (clipsAPI.h: VtArray<SdfAssetPath> asset
// paths, VtVec2dArray active and times); absent or malformed is empty.
function typedField<T>(value: unknown, typeName: string): VtArray<T> {
  const typed = value === undefined ? undefined : _sdfCoerceValueToType(value, typeName)
  return typed instanceof VtArray ? typed as VtArray<T>
    : _sdfCoerceValueToType([], typeName) as VtArray<T>
}
